 "content": "from collections import Counter

def transform(grid):
    """Select the most numerous non-background color and return its 3x3 marker.

    The two most frequent nonzero colors are the scattered background texture;
    among remaining colors, the color with the greatest cell count is selected.
    """
    counts = Counter(value for row in grid for value in row if value != 0)
    background_colors = {color for color, _ in counts.most_common(2)}
    foreground_counts = {
        color: count for color, count in counts.items()
        if color not in background_colors
    }
    selected = max(foreground_counts, key=foreground_counts.get)
    return [[selected] * 3 for _ in range(3)]
